<?php require_once 'config.php'; if(logged_in()) redirect('dashboard.php'); $pageTitle='Create account'; $errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$password=$_POST['password']??'';$role=$_POST['role']??'trainee';if($name==='')$errors[]='Please enter your name.';if(!filter_var($email,FILTER_VALIDATE_EMAIL))$errors[]='Enter a valid email address.';if(strlen($password)<8)$errors[]='Password must be at least 8 characters.';if(!in_array($role,['trainee','trainer'],true))$errors[]='Choose a valid account type.';if(!$errors){try{$s=db()->prepare('INSERT INTO users(name,email,password,role) VALUES(?,?,?,?)');$s->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT),$role]);flash('Account created. Welcome to Capacity Connect!');redirect('login.php');}catch(PDOException $e){$errors[]=$e->getCode()==='23000'?'That email address is already registered.':'Could not create your account. Please try again.';}}}
require 'includes/header.php'; ?>
<section class="auth-layout"><div class="auth-aside"><span class="eyebrow">MAKE ROOM TO GROW</span><h1>Your next chapter<br>starts with <em>learning.</em></h1><p>Join a connected community of learners and trainers. Build your skills one step at a time.</p><div class="aside-note">✦ <span>One platform. Many possibilities.</span></div></div><div class="auth-card"><span class="eyebrow">GET STARTED</span><h2>Create your account</h2><p class="muted">Choose how you'd like to use the platform.</p><?php foreach($errors as $err): ?><div class="alert error"><?= e($err) ?></div><?php endforeach; ?><form method="post" class="form-stack"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><label>Full name<input name="name" required value="<?= e($_POST['name']??'') ?>" placeholder="e.g. Vinay Jadav"></label><label>Email address<input type="email" name="email" required value="<?= e($_POST['email']??'') ?>" placeholder="you@example.com"></label><label>Account type<select name="role"><option value="trainee">Trainee / Learner</option><option value="trainer" <?= ($_POST['role']??'')==='trainer'?'selected':'' ?>>Trainer</option></select></label><label>Password<input type="password" name="password" minlength="8" required placeholder="At least 8 characters"></label><button class="btn btn-primary btn-full">Create account →</button></form><p class="auth-switch">Already registered? <a href="login.php">Log in</a></p><p class="tiny-note">Administrator accounts are created by the system administrator.</p></div></section>
